<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requirePermission('competitors.edit');$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$pdo->prepare('SELECT id,identity_code,display_name,entry_type,solo_competitor_id,photo_url FROM bdc_wdc_identities WHERE id=:id');$stmt->execute(['id'=>$id]);$row=$stmt->fetch();if(!$row){http_response_code(404);exit('WDC competitor not found.');}$error='';$sharedPhoto='';if((int)($row['solo_competitor_id']??0)>0){try{$stmt=$pdo->prepare('SELECT photo_url FROM bdc_competitors WHERE id=:id');$stmt->execute(['id'=>(int)$row['solo_competitor_id']]);$sharedPhoto=trim((string)$stmt->fetchColumn());}catch(Throwable $ignored){}}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token. Refresh and try again.');$directory=dirname(__DIR__,2).'/uploads/wdc';if(!is_dir($directory)&&!mkdir($directory,0755,true)&&!is_dir($directory))throw new RuntimeException('Photo upload folder is unavailable.');if(($_POST['action']??'replace')==='crop'){$data=(string)($_POST['cropped_photo_data']??'');if(!preg_match('~^data:image/jpeg;base64,([A-Za-z0-9+/=]+)$~',$data,$match))throw new RuntimeException('Adjust the photo before saving.');$bytes=base64_decode($match[1],true);if($bytes===false||strlen($bytes)>4*1024*1024)throw new RuntimeException('Adjusted photo is invalid.');$filename='wdc-framed-'.$id.'-'.bin2hex(random_bytes(6)).'.jpg';if(file_put_contents($directory.'/'.$filename,$bytes)===false)throw new RuntimeException('Adjusted photo could not be saved.');$action='wdc_photo_adjusted';}else{$file=$_FILES['photo']??null;if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a JPG, PNG or WebP photo.');if((int)($file['size']??0)>8*1024*1024)throw new RuntimeException('Photo must be under 8 MB.');$temporary=(string)($file['tmp_name']??'');$mime='';if(class_exists('finfo'))$mime=(string)(new finfo(FILEINFO_MIME_TYPE))->file($temporary);elseif(function_exists('mime_content_type'))$mime=(string)mime_content_type($temporary);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))throw new RuntimeException('Photo must be a valid JPG, PNG or WebP image.');$filename='wdc-'.$id.'-'.bin2hex(random_bytes(6)).'.'.$types[$mime];if(!move_uploaded_file($temporary,$directory.'/'.$filename))throw new RuntimeException('Photo could not be uploaded.');$action='wdc_photo_replaced';}$photo=url('uploads/wdc/'.$filename);$pdo->prepare('UPDATE bdc_wdc_identities SET photo_url=:photo WHERE id=:id')->execute(['photo'=>$photo,'id'=>$id]);Auth::audit((int)(Auth::user()['id']??0),$action,[],'wdc_identity',$id);header('Location: photo-adjust.php?id='.$id,true,303);exit;}catch(Throwable $exception){$error=$exception->getMessage();}}
$photo=trim((string)$row['photo_url']);if($photo==='')$photo=$sharedPhoto;if($photo==='')$photo=url('public/assets/img/default-competitor.svg');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Adjust WDC Photo</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>body{background:linear-gradient(135deg,#edf3fb,#f8f9fc 55%,#f3edf7);color:#111c33}.hero{background:linear-gradient(120deg,#0d1b36,#172c54 65%,#511933);color:#fff;border-radius:22px;padding:22px}.panel{border:1px solid #fff;border-radius:20px;background:#ffffffef;box-shadow:0 14px 34px #20325414}.crop{width:min(360px,100%);aspect-ratio:4/5;overflow:hidden;background:#dce3ec;border-radius:20px;position:relative;touch-action:none;user-select:none}.crop img{position:absolute;max-width:none;pointer-events:none;-webkit-user-drag:none}.crop.is-dragging{cursor:grabbing}</style></head><body><main class="container py-4" style="max-width:900px"><section class="hero mb-4"><div class="d-flex justify-content-between gap-3"><div><div class="small text-info fw-bold">WDC PHOTO STUDIO</div><h1 class="h2 mb-1">Adjust competitor photo</h1><p class="mb-0 text-white-50"><?=e($row['identity_code'])?> · <?=e($row['display_name'])?></p></div><a class="btn btn-light align-self-start" href="competitor-edit.php?id=<?=$id?>">Back</a></div></section><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4"><div class="col-lg-7"><form method="post" id="cropForm" class="panel overflow-hidden"><div class="p-4"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="crop"><input type="hidden" name="cropped_photo_data" id="cropData"><div class="crop mx-auto" id="frame"><img id="photo" src="<?=e($photo)?>" crossorigin="anonymous" draggable="false"></div><label class="form-label fw-bold mt-4">Zoom</label><input class="form-range" id="zoom" type="range" min="1" max="3" step=".01" value="1"><p class="small text-muted mb-0">Drag the photo to reposition it inside the portrait frame.</p></div><div class="p-3 bg-white border-top text-end"><button class="btn btn-primary">Save adjusted photo</button></div></form></div><div class="col-lg-5"><form method="post" enctype="multipart/form-data" class="panel p-4"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="replace"><h2 class="h5">Replace original</h2><p class="small text-muted">Upload JPG, PNG or WebP up to 8 MB, then position it in the studio.</p><input class="form-control mb-3" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><button class="btn btn-outline-primary w-100">Upload replacement</button><hr><p class="small text-muted mb-0">This changes only the WDC identity. BDC and SDC photos remain untouched.</p></form></div></div></main><script>const frame=document.getElementById('frame'),img=document.getElementById('photo'),zoom=document.getElementById('zoom');let x=0,y=0,drag=false,pointerId=null,sx=0,sy=0,raf=0;function metrics(){const w=frame.clientWidth,h=frame.clientHeight,base=Math.max(w/img.naturalWidth,h/img.naturalHeight),scale=base*Number(zoom.value);return{w,h,iw:img.naturalWidth*scale,ih:img.naturalHeight*scale}}function draw(){cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{if(!img.naturalWidth)return;const m=metrics(),maxX=Math.max(0,(m.iw-m.w)/2),maxY=Math.max(0,(m.ih-m.h)/2);x=Math.max(-maxX,Math.min(maxX,x));y=Math.max(-maxY,Math.min(maxY,y));img.style.width=m.iw+'px';img.style.height=m.ih+'px';img.style.left=(m.w/2-m.iw/2+x)+'px';img.style.top=(m.h/2-m.ih/2+y)+'px'})}function stop(e){drag=false;pointerId=null;frame.classList.remove('is-dragging');if(e)e.preventDefault()}img.onload=draw;zoom.addEventListener('input',draw);window.addEventListener('resize',draw);frame.addEventListener('pointerdown',e=>{drag=true;pointerId=e.pointerId;sx=e.clientX-x;sy=e.clientY-y;frame.classList.add('is-dragging');frame.setPointerCapture?.(e.pointerId);e.preventDefault()});frame.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==pointerId)return;x=e.clientX-sx;y=e.clientY-sy;draw();e.preventDefault()});['pointerup','pointercancel','lostpointercapture'].forEach(type=>frame.addEventListener(type,stop));document.getElementById('cropForm').onsubmit=()=>{const canvas=document.createElement('canvas');canvas.width=720;canvas.height=900;const context=canvas.getContext('2d'),r=img.getBoundingClientRect(),f=frame.getBoundingClientRect(),scaleX=720/f.width,scaleY=900/f.height;context.drawImage(img,(r.left-f.left)*scaleX,(r.top-f.top)*scaleY,r.width*scaleX,r.height*scaleY);document.getElementById('cropData').value=canvas.toDataURL('image/jpeg',.9)};</script></body></html>
